CREATE SCHEMA cricket_source_v1;
SET search_path=cricket_source_v1,pg_catalog;
CREATE TABLE proof_environment(singleton BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK(singleton),schema_sha256 TEXT NOT NULL,cluster_run_id TEXT NOT NULL);
CREATE TABLE import_runs(run_id TEXT PRIMARY KEY,manifest_sha256 TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('cohort','full')),expected_matches INTEGER NOT NULL CHECK(expected_matches>0),held_count INTEGER NOT NULL CHECK(held_count>=0),full_admitted_snapshot_ready BOOLEAN NOT NULL,provenance JSONB NOT NULL,imported_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE players(player_id TEXT PRIMARY KEY,espn_id BIGINT UNIQUE NOT NULL CHECK(espn_id>0),name TEXT,CHECK(player_id='espn_'||espn_id::text));
CREATE TABLE player_aliases(source TEXT NOT NULL,source_id TEXT NOT NULL,player_id TEXT NOT NULL REFERENCES players,PRIMARY KEY(source,source_id));
CREATE TABLE matches(match_id TEXT PRIMARY KEY CHECK(match_id~'^[0-9]+$'),run_id TEXT NOT NULL REFERENCES import_runs,date DATE,season TEXT,format_bucket TEXT NOT NULL,record_class TEXT NOT NULL,playing_format TEXT NOT NULL,balls_per_group INTEGER NOT NULL CHECK(balls_per_group>0),competition TEXT,trophy_id BIGINT,venue TEXT,venue_country TEXT,city TEXT,gender TEXT,outcome JSONB NOT NULL,toss JSONB NOT NULL,meta JSONB NOT NULL);
CREATE TABLE match_teams(match_id TEXT REFERENCES matches,team_name TEXT NOT NULL,PRIMARY KEY(match_id,team_name));
CREATE TABLE participants(match_id TEXT REFERENCES matches,player_id TEXT REFERENCES players,source_name TEXT,roles JSONB NOT NULL,team_source_ids JSONB NOT NULL,source_facts JSONB NOT NULL,PRIMARY KEY(match_id,player_id));
CREATE TABLE lineup_assertions(match_id TEXT,team_name TEXT,status TEXT NOT NULL,PRIMARY KEY(match_id,team_name),FOREIGN KEY(match_id,team_name) REFERENCES match_teams);
CREATE TABLE lineup_members(match_id TEXT,team_name TEXT,position INTEGER CHECK(position>0),player_id TEXT,PRIMARY KEY(match_id,team_name,position),FOREIGN KEY(match_id,team_name) REFERENCES lineup_assertions,FOREIGN KEY(match_id,player_id) REFERENCES participants);
CREATE TABLE participation_events(match_id TEXT REFERENCES matches,event_ordinal INTEGER CHECK(event_ordinal>0),event_type TEXT NOT NULL,incoming_player_id TEXT REFERENCES players,outgoing_player_id TEXT REFERENCES players,source_facts JSONB NOT NULL,PRIMARY KEY(match_id,event_ordinal));
CREATE TABLE innings(match_id TEXT,innings_number INTEGER CHECK(innings_number>0),batting_team TEXT NOT NULL,bowling_team TEXT NOT NULL,standard_stats BOOLEAN NOT NULL,super_over BOOLEAN NOT NULL,innings_kind TEXT,penalty_runs INTEGER NOT NULL CHECK(penalty_runs>=0),actual_legal_balls INTEGER NOT NULL CHECK(actual_legal_balls>=0),source_scorecard_balls INTEGER CHECK(source_scorecard_balls>=0),source_only_timed_out INTEGER CHECK(source_only_timed_out>=0),source_scorecard JSONB NOT NULL,metadata JSONB NOT NULL,PRIMARY KEY(match_id,innings_number),FOREIGN KEY(match_id) REFERENCES matches,FOREIGN KEY(match_id,batting_team) REFERENCES match_teams,FOREIGN KEY(match_id,bowling_team) REFERENCES match_teams);
CREATE TABLE deliveries(
 match_id TEXT,innings_number INTEGER,ordinal INTEGER CHECK(ordinal>0),group_number INTEGER NOT NULL CHECK(group_number>=0),event_ball_number INTEGER NOT NULL CHECK(event_ball_number>0),
 batter_id TEXT NOT NULL REFERENCES players,bowler_id TEXT NOT NULL REFERENCES players,non_striker_id TEXT REFERENCES players,legal BOOLEAN NOT NULL,
 legal_before INTEGER NOT NULL CHECK(legal_before>=0),legal_after INTEGER NOT NULL CHECK(legal_after>=0),
 batter_observed INTEGER NOT NULL CHECK(batter_observed>=0),extras_observed INTEGER NOT NULL CHECK(extras_observed>=0),total_observed INTEGER NOT NULL CHECK(total_observed>=0),
 wides_observed INTEGER NOT NULL CHECK(wides_observed>=0),noballs_observed INTEGER NOT NULL CHECK(noballs_observed>=0),byes_observed INTEGER NOT NULL CHECK(byes_observed>=0),legbyes_observed INTEGER NOT NULL CHECK(legbyes_observed>=0),penalties_observed INTEGER NOT NULL CHECK(penalties_observed>=0),
 batter_scored INTEGER NOT NULL CHECK(batter_scored>=0),extras_scored INTEGER NOT NULL CHECK(extras_scored>=0),total_scored INTEGER NOT NULL CHECK(total_scored>=0),
 wides_scored INTEGER NOT NULL CHECK(wides_scored>=0),noballs_scored INTEGER NOT NULL CHECK(noballs_scored>=0),byes_scored INTEGER NOT NULL CHECK(byes_scored>=0),legbyes_scored INTEGER NOT NULL CHECK(legbyes_scored>=0),penalties_scored INTEGER NOT NULL CHECK(penalties_scored>=0),bowler_charge INTEGER NOT NULL CHECK(bowler_charge>=0),
 phase TEXT NOT NULL,nominal_phase TEXT,source_marker TEXT,source_unique_marker TEXT,source_group_number INTEGER,tactical JSONB,review JSONB,
 PRIMARY KEY(match_id,innings_number,ordinal),FOREIGN KEY(match_id,innings_number) REFERENCES innings,FOREIGN KEY(match_id,batter_id) REFERENCES participants,FOREIGN KEY(match_id,bowler_id) REFERENCES participants,FOREIGN KEY(match_id,non_striker_id) REFERENCES participants,
 CHECK(total_observed=batter_observed+extras_observed),CHECK(extras_observed=wides_observed+noballs_observed+byes_observed+legbyes_observed+penalties_observed),
 CHECK(total_scored=batter_scored+extras_scored),CHECK(extras_scored=wides_scored+noballs_scored+byes_scored+legbyes_scored+penalties_scored),
 CHECK(total_scored=total_observed),CHECK(bowler_charge=batter_scored+wides_scored+noballs_scored),
 CHECK(legal=(wides_observed=0 AND noballs_observed=0)),CHECK(legal=(wides_scored=0 AND noballs_scored=0)),CHECK(legal_after=legal_before+CASE WHEN legal THEN 1 ELSE 0 END));
CREATE TABLE dismissal_events(match_id TEXT,innings_number INTEGER,event_key TEXT,delivery_ordinal INTEGER,player_out_id TEXT REFERENCES players,kind TEXT NOT NULL,source_only BOOLEAN NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),team_wickets INTEGER NOT NULL CHECK(team_wickets>=0),batter_dismissals INTEGER CHECK(batter_dismissals>=0),bowler_wickets INTEGER NOT NULL CHECK(bowler_wickets>=0),fielders JSONB NOT NULL,source_facts JSONB NOT NULL,PRIMARY KEY(match_id,innings_number,event_key),FOREIGN KEY(match_id,innings_number) REFERENCES innings,FOREIGN KEY(match_id,player_out_id) REFERENCES participants,FOREIGN KEY(match_id,innings_number,delivery_ordinal) REFERENCES deliveries(match_id,innings_number,ordinal),CHECK((source_only AND delivery_ordinal IS NULL AND player_out_id IS NULL AND batter_dismissals IS NULL AND bowler_wickets=0) OR (NOT source_only AND delivery_ordinal IS NOT NULL AND player_out_id IS NOT NULL AND batter_dismissals IS NOT NULL)));
CREATE TABLE source_documents(match_id TEXT PRIMARY KEY REFERENCES matches,payload_gzip BYTEA NOT NULL,payload_sha256 TEXT NOT NULL CHECK(payload_sha256~'^[a-f0-9]{64}$'),source_sha256 TEXT NOT NULL CHECK(source_sha256~'^[a-f0-9]{64}$'));
CREATE TABLE source_holds(match_id TEXT PRIMARY KEY,stage TEXT NOT NULL,reason JSONB NOT NULL,manifest_sha256 TEXT NOT NULL);
CREATE INDEX deliveries_batter ON deliveries(batter_id,match_id,innings_number);
CREATE INDEX deliveries_bowler ON deliveries(bowler_id,match_id,innings_number);
CREATE INDEX dismissals_actor ON dismissal_events(player_out_id,match_id,innings_number);
CREATE INDEX matches_format_date ON matches(format_bucket,date);

CREATE VIEW v_innings_totals AS
 WITH runs AS(SELECT match_id,innings_number,COUNT(*) AS delivered_balls,COUNT(*) FILTER(WHERE legal) AS actual_balls,SUM(total_scored) AS delivery_runs,SUM(extras_scored) AS delivery_extras,COUNT(*) FILTER(WHERE non_striker_id IS NULL) AS unknown_non_strikers FROM deliveries GROUP BY match_id,innings_number),
 wickets AS(SELECT match_id,innings_number,SUM(team_wickets) AS team_wickets,SUM(team_wickets) FILTER(WHERE source_only) AS unattributed_wickets FROM dismissal_events GROUP BY match_id,innings_number)
 SELECT i.match_id,i.innings_number,i.batting_team,i.bowling_team,i.standard_stats,i.super_over,i.innings_kind,m.format_bucket,m.playing_format,m.balls_per_group,COALESCE(r.delivered_balls,0) AS delivered_balls,COALESCE(r.actual_balls,0) AS actual_legal_balls,i.source_scorecard_balls,COALESCE(r.delivery_runs,0)+i.penalty_runs AS team_runs,COALESCE(r.delivery_extras,0)+i.penalty_runs AS extras,i.penalty_runs,COALESCE(w.team_wickets,0) AS team_wickets,COALESCE(w.unattributed_wickets,0) AS unattributed_wickets,COALESCE(r.unknown_non_strikers,0) AS unknown_non_strikers,i.source_scorecard,i.metadata
 FROM innings i JOIN matches m USING(match_id) LEFT JOIN runs r USING(match_id,innings_number) LEFT JOIN wickets w USING(match_id,innings_number);

CREATE VIEW v_batter_totals AS
 WITH bat AS(SELECT match_id,innings_number,batter_id AS player_id,SUM(batter_scored) AS runs,COUNT(*) FILTER(WHERE wides_observed=0) AS balls_faced FROM deliveries GROUP BY match_id,innings_number,batter_id),
 outs AS(SELECT match_id,innings_number,player_out_id AS player_id,SUM(batter_dismissals) AS dismissals FROM dismissal_events WHERE player_out_id IS NOT NULL GROUP BY match_id,innings_number,player_out_id),
 totals AS(SELECT COALESCE(b.match_id,o.match_id) AS match_id,COALESCE(b.innings_number,o.innings_number) AS innings_number,COALESCE(b.player_id,o.player_id) AS player_id,COALESCE(b.runs,0) AS runs,COALESCE(b.balls_faced,0) AS balls_faced,COALESCE(o.dismissals,0) AS dismissals FROM bat b FULL JOIN outs o USING(match_id,innings_number,player_id))
 SELECT t.*,i.standard_stats,m.format_bucket,m.date,ROUND(t.runs*100.0/NULLIF(t.balls_faced,0),2) AS strike_rate,ROUND(t.runs::numeric/NULLIF(t.dismissals,0),2) AS average FROM totals t JOIN innings i USING(match_id,innings_number) JOIN matches m USING(match_id);

CREATE VIEW v_bowler_totals AS
 WITH bowl AS(SELECT match_id,innings_number,bowler_id AS player_id,SUM(bowler_charge) AS runs_conceded,COUNT(*) FILTER(WHERE legal) AS actual_legal_balls,COUNT(*) FILTER(WHERE noballs_observed>0) AS no_ball_deliveries,SUM(noballs_scored) AS credited_no_ball_runs FROM deliveries GROUP BY match_id,innings_number,bowler_id),
 wickets AS(SELECT e.match_id,e.innings_number,d.bowler_id AS player_id,SUM(e.bowler_wickets) AS wickets FROM dismissal_events e JOIN deliveries d ON(d.match_id=e.match_id AND d.innings_number=e.innings_number AND d.ordinal=e.delivery_ordinal) WHERE e.bowler_wickets>0 GROUP BY e.match_id,e.innings_number,d.bowler_id)
 SELECT b.*,COALESCE(w.wickets,0) AS wickets,i.standard_stats,m.format_bucket,m.date,6 AS rate_basis_balls,ROUND(b.runs_conceded*6.0/NULLIF(b.actual_legal_balls,0),2) AS economy,ROUND(b.runs_conceded::numeric/NULLIF(w.wickets,0),2) AS bowling_average,ROUND(b.actual_legal_balls::numeric/NULLIF(w.wickets,0),2) AS bowling_strike_rate FROM bowl b JOIN innings i USING(match_id,innings_number) JOIN matches m USING(match_id) LEFT JOIN wickets w USING(match_id,innings_number,player_id);

CREATE VIEW v_phase_totals AS
 SELECT d.match_id,d.innings_number,d.phase,COUNT(*) AS delivered_balls,COUNT(*) FILTER(WHERE d.legal) AS actual_legal_balls,SUM(d.total_scored) AS runs FROM deliveries d GROUP BY d.match_id,d.innings_number,d.phase;
